const e=[{title:"NLP Fundamentals and Challenges",subtitle:"Why Natural Language Is Difficult for Machines",imageUrls:["https://upload.wikimedia.org/wikipedia/commons/7/79/Major_levels_of_linguistic_structure.svg"],bullets:[{text:"Natural language is ambiguous, context-dependent, and full of idioms.",icon:"nlp"},{text:"Meaning often depends on pragmatics, domain, and cultural background.",icon:"rag"},{text:"The same sentence can map to multiple valid interpretations.",icon:"test"}],note:"NLP systems must model form, meaning, and context simultaneously.",speakerNote:"NLP systems must model form, meaning, and context simultaneously.",titleIcon:"nlp"},{title:"Ambiguity in Language: Practical Examples",table:{headers:["Expression","Possible Interpretation A","Possible Interpretation B"],rows:[["The bank is closed","Financial institution is closed","River bank area is inaccessible"],["It's cold","Low temperature","Emotionally distant behavior"],["The chicken is ready to eat","Food is ready to be eaten","Animal is ready to eat food"]]},note:"Robust NLP requires disambiguation using surrounding textual and situational context.",speakerNote:"Robust NLP requires disambiguation using surrounding textual and situational context.",titleIcon:"idea"},{title:"NLP Grand Goal and Core Applications",sections:[{heading:"Grand Goal",bullets:[{text:"Human-level language understanding with nuance, intent, and context.",icon:"nlp"},{text:"Natural human-machine interaction over text and speech.",icon:"nlp"}]},{heading:"Applications",bullets:[{text:"Machine translation, sentiment analysis, question answering, search.",icon:"nlp"},{text:"Conversational assistants, customer support automation, social analytics.",icon:"nlp"}]}],speakerNote:'Present "NLP Grand Goal and Core Applications". Tie back to the section objective and invite one question before advancing.',titleIcon:"nlp"},{title:"Regular Expressions (Regex): Core Idea",bullets:[{text:"Regex is a compact pattern language for matching and transforming text.",icon:"idea"},{text:"Typical uses include validation, extraction, and rule-based cleanup.",icon:"test"},{text:"Useful for emails, phone numbers, logs, and normalization pipelines.",icon:"scaling"}],table:{headers:["Pattern","Meaning","Example Match"],rows:[["\\d+","one or more digits","2026"],["\\w+","one or more word chars","nlp_model1"],["^[A-Z]","starts with uppercase letter","Hello"],["\\S+","one or more non-space chars","token123"]]},speakerNote:'Cover "Regular Expressions (Regex): Core Idea". Emphasize: Regex is a compact pattern language for matching and transforming text.; then Typical uses include validation, extraction, and rule-based cleanup.. Pause for a quick check-in before moving on.',titleIcon:"idea"},{title:"Regex Quantifiers and Boundaries",table:{headers:["Regex Element","Role","Example"],rows:[["*","zero or more occurrences","ba* -> b, ba, baaa"],["+","one or more occurrences","\\d+ -> 4, 2024"],["|","OR between alternatives","cat|dog"],["\\b","word boundary","\\bing\\b matches standalone 'ing'"],["^ / $","start / end anchors","^The, end$"]]},note:"Boundary-aware regex prevents false matches inside larger words.",speakerNote:"Boundary-aware regex prevents false matches inside larger words.",titleIcon:"idea"},{title:"Regex Refinement Workflow",bullets:[{text:"Initial pattern may under-match or over-match.",icon:"idea"},{text:"Iteratively refine with case handling and boundaries.",icon:"idea"},{text:'Use raw strings in Python regex (e.g., r"\\d+") to avoid escaping pitfalls.',icon:"warning"}],table:{headers:["Iteration","Pattern","Issue / Improvement"],rows:[["1","the","Misses uppercase forms like 'The'"],["2","[tT]he","Matches both cases but may hit substrings (e.g., other)"],["3","\\W[tT]he\\W","Targets standalone word occurrences"]]},speakerNote:'Cover "Regex Refinement Workflow". Emphasize: Initial pattern may under-match or over-match.; then Iteratively refine with case handling and boundaries.. Pause for a quick check-in before moving on.',titleIcon:"idea"},{title:"Words and Corpora: Tokens vs Types",bullets:[{text:"Tokens are total observed word instances (with repetition).",icon:"token"},{text:"Types are unique vocabulary items in the corpus.",icon:"token"},{text:"Corpus statistics vary by language, genre, time, and author demographics.",icon:"token"}],table:{headers:["Text","Tokens (N)","Types (|V|)"],rows:[["the cat sat on the mat","6","5"],["NLP models learn from repeated contexts","6","6"]]},speakerNote:'Cover "Words and Corpora: Tokens vs Types". Emphasize: Tokens are total observed word instances (with repetition).; then Types are unique vocabulary items in the corpus.. Pause for a quick check-in before moving on.',titleIcon:"token",conceptAnimation:"tokenization-flow"},{title:"Heaps' Law in NLP Corpora",formula:"|V| = kN^b,\\quad 0 < b < 1",bullets:[{text:"Vocabulary size grows with corpus size, but sublinearly.",icon:"regression"},{text:"Early in corpus growth, many new words appear quickly.",icon:"nlp"},{text:"Later growth adds fewer unseen types per additional token.",icon:"token"}],note:"This behavior motivates subword methods and scalable vocabulary design.",speakerNote:"This behavior motivates subword methods and scalable vocabulary design.",titleIcon:"nlp"},{title:"Text Normalization Pipeline",subtitle:"Prepare Raw Text for Modeling",sections:[{heading:"Core Steps",bullets:[{text:"Tokenize text (word/subword/sentence segmentation).",icon:"token"},{text:"Lowercase (task-dependent), remove noisy symbols, clean markup.",icon:"regression"},{text:"Normalize word forms via stemming or lemmatization.",icon:"scaling"}]},{heading:"Why It Matters",bullets:[{text:"Reduces noise and redundancy in unstructured text.",icon:"scaling"},{text:"Improves downstream feature quality and model robustness.",icon:"feature"}]}],speakerNote:'Present "Text Normalization Pipeline". Tie back to the section objective and invite one question before advancing.',titleIcon:"scaling",conceptAnimation:"feature-scaling"},{title:"Text Preprocessing Techniques (Operational View)",table:{headers:["Technique","Purpose","Example"],rows:[["Remove HTML tags","Drop markup noise","<p>Hello</p> -> Hello"],["Remove URLs","Keep linguistic content only","visit https://... -> visit"],["Remove punctuation","Standardize lexical forms","hello, world! -> hello world"],["Handle chat words/emojis","Preserve semantic sentiment cues","gr8 -> great, :) -> positive_emoji"],["Stopword handling","Reduce weakly informative tokens","the, is, and"]]},speakerNote:'Present "Text Preprocessing Techniques (Operational View)". Tie back to the section objective and invite one question before advancing.',titleIcon:"pipeline",illustration:"preprocessing-pipeline"},{title:"Tokenization Strategies",bullets:[{text:"Whitespace tokenization is simple and effective for many scripts.",icon:"token"},{text:"Character-level tokenization avoids OOV but can lengthen sequences.",icon:"token"},{text:"Subword tokenization balances vocabulary size and semantic coverage.",icon:"token"}],table:{headers:["Strategy","Strength","Tradeoff"],rows:[["Word/space-based","Human-readable tokens","Weak on rare/compound words"],["Character-based","No unknown words","Very long sequences"],["Subword-based","Handles rare words and morphology","Tokenizer training complexity"]]},speakerNote:'Cover "Tokenization Strategies". Emphasize: Whitespace tokenization is simple and effective for many scripts.; then Character-level tokenization avoids OOV but can lengthen sequences.. Pause for a quick check-in before moving on.',titleIcon:"token",conceptAnimation:"tokenization-flow"},{title:"Subword Tokenization Algorithms",table:{headers:["Algorithm","Base Idea","Common Usage"],rows:[["BPE","Merge most frequent adjacent units iteratively","GPT-family style tokenizers"],["WordPiece","Likelihood-driven merges","BERT-family models"],["Unigram LM","Probabilistic token inventory pruning","T5/XLNet-style pipelines"],["SentencePiece","Train on raw text without pre-tokenization","Multilingual pipelines"]]},note:"Subword methods control vocabulary growth while preserving useful semantics.",speakerNote:"Subword methods control vocabulary growth while preserving useful semantics.",titleIcon:"token",conceptAnimation:"tokenization-flow"},{title:"Unigram LM Tokenization Example",bullets:[{text:"Model evaluates multiple candidate segmentations with token probabilities.",icon:"test"},{text:"Chooses segmentation with highest likelihood for each word context.",icon:"token"},{text:"EM training updates token probabilities and prunes weak tokens.",icon:"train"}],table:{headers:["Candidate Tokenization","Score"],rows:[["basket + ball","0.30"],["basketball","0.40"],["bask + etball","0.06"]]},note:"Highest-probability segmentation is selected in decoding.",speakerNote:"Highest-probability segmentation is selected in decoding.",titleIcon:"token",conceptAnimation:"tokenization-flow"},{title:"BPE Training Process",bullets:[{text:"Start from character-level symbols.",icon:"regression"},{text:"Count adjacent symbol-pair frequencies.",icon:"token"},{text:"Merge most frequent pair into a new token.",icon:"token"},{text:"Repeat until target vocabulary size is reached.",icon:"token"}],table:{headers:["Step","Operation"],rows:[["1","Initialize symbol inventory"],["2","Compute pair frequencies"],["3","Merge best pair"],["4","Rebuild sequence with merged token and iterate"]]},speakerNote:'Cover "BPE Training Process". Emphasize: Start from character-level symbols.; then Count adjacent symbol-pair frequencies.. Pause for a quick check-in before moving on.',titleIcon:"token",conceptAnimation:"tokenization-flow"},{title:"Stemming vs Lemmatization",table:{headers:["Aspect","Stemming","Lemmatization"],rows:[["Method","Rule-based suffix stripping","Vocabulary + morphology aware normalization"],["Output quality","May produce non-words (studi)","Canonical dictionary forms (study)"],["Context sensitivity","Low","Higher (POS-aware)"],["Use case","Fast retrieval/indexing","Semantically cleaner linguistic analysis"]]},note:"Choose based on task priority: speed and recall vs linguistic precision.",speakerNote:"Choose based on task priority: speed and recall vs linguistic precision.",titleIcon:"idea"},{title:"Lemmatization and Morphology Examples",bullets:[{text:"Verb forms: am/are/is/was/were -> be.",icon:"idea"},{text:"Irregular nouns: mice -> mouse, children -> child.",icon:"idea"},{text:"POS-aware cases: better (adj) -> good, better (verb) -> better.",icon:"idea"}],note:"Lemmatization preserves semantics better than aggressive stemming.",speakerNote:"Lemmatization preserves semantics better than aggressive stemming.",titleIcon:"idea"},{title:"Modern NLP Models: From Embeddings to Transformers",imageUrls:["https://upload.wikimedia.org/wikipedia/commons/d/dd/Continuous_Bag_of_Words_model_%28CBOW%29.svg","https://upload.wikimedia.org/wikipedia/commons/3/34/Transformer%2C_full_architecture.png"],bullets:[{text:"Distributed embeddings (e.g., CBOW) map words into dense semantic vectors.",icon:"embedding"},{text:"Transformers model long-range dependencies via self-attention.",icon:"attention"},{text:"Current NLP systems combine strong preprocessing with large pretrained models.",icon:"train"}],speakerNote:'Cover "Modern NLP Models: From Embeddings to Transformers". Emphasize: Distributed embeddings (e.g., CBOW) map words into dense semantic vectors.; then Transformers model long-range dependencies via self-attention.. Pause for a quick check-in before moving on.',titleIcon:"embedding"},{title:"Transformer Encoder-Decoder Overview",imageUrls:["https://upload.wikimedia.org/wikipedia/commons/4/49/Attention_Is_All_You_Need_-_Encoder-decoder_Architecture.png"],bullets:[{text:"Encoder builds contextual token representations from source text.",icon:"encoding"},{text:"Decoder generates target tokens autoregressively with attention to encoder states.",icon:"encoding"},{text:"Foundation architecture for translation, summarization, and many LLM pipelines.",icon:"llm"}],note:"Attention mechanisms reduce reliance on recurrence for sequence modeling.",speakerNote:"Attention mechanisms reduce reliance on recurrence for sequence modeling.",titleIcon:"encoding",conceptAnimation:"encoding-comparison"}];export{e as slides};
